227: void CIconBarSet::CreateButton( int nNormalIcon, int nDisabledIcon, CComplexButton::EState eState, int nToolTipID, int nSlot, int nPriority, int nUnitAction, int nUnitState, const string &szID )
228: {
229: 	int nState = pMission->GetUnitsWorldState();
230: 	if ( ( nUnitState != N_ANY_VALUE ) && ( nUnitState != nState ) )
231: 		return;
232: 	if ( iconsSet[nSlot].nPriority < nPriority )
233: 		return;
234: 
235: 	NGame::SActionInfo sActionInfo;
236: 	pMission->GetActionInfo( NGame::EUnitAction( nUnitAction ), &sActionInfo );
237: 	if ( !sActionInfo.bAvailable )
238: 		return;
239: 
240: 	CPtr<NDb::CUITexture> pNormalIcon, pCheckedIcon, pDisabledIcon;
241: 	if ( nNormalIcon != -1 )
242: 		pNormalIcon = NDb::GetUITexture( nNormalIcon );
243: 	if ( nDisabledIcon != -1 )
244: 		pDisabledIcon = NDb::GetUITexture( nDisabledIcon );
245: 
246: 	iconsSet[nSlot].nPriority = nPriority;
247: 
248: 	CPtr<CComplexButton> pButton = iconsSet[nSlot].pButton;
249: 	pButton->Set( pNormalIcon, pDisabledIcon, eState, szID );

253: void CComplexButton::Set( NDb::CUITexture *pIcon, NDb::CUITexture *pIconDisabled, EState eState, const string &szID )
254: {
255: 	pDisabled->SetImage( pIconDisabled );
256: 
257: 	pNormalUpIcon->SetImage( pIcon );
258: 	pNormalDownIcon->SetImage( pIcon );
259: 
260: 	pCheckedUpIcon->SetImage( pIcon );
261: 	pCheckedDownIcon->SetImage( pIcon );
262: 
263: 	pNormalUpCheck->SetStyle( STYLE_VISIBLE, eState != NORMAL );
264: 	pNormalDownCheck->SetStyle( STYLE_VISIBLE, eState != NORMAL );
265: 
266: 	SetChecked( eState == CHECKED );
267: 	SetNotifyID( szID );
268: }

